 rating.append(profileValues([['Место',format(p.rank)],['MMR',format(p.mmr)],['Опыт',format(p.xp)],['Прогресс уровня',(p.progress??0)+'%'],['Игры',format(p.rated_games)],['Победы',format(p.wins)],['Поражения',format(p.losses)]]));
